//! HE-AAC v1 (SBR) and v2 (Parametric Stereo) parity against FFmpeg, from stored references.
//!
//! Fixtures live in `tests/data/he/` and are generated by `scripts/aac-tables/make-he-fixtures.sh`.
//! Each stream is written as ADTS (`.aac`) and MP4 (`.m4a`). The reference is FFmpeg's own decode
//! of the `.aac`, stored next to it as signed 16-bit little-endian PCM (`.s16`), in FFmpeg's channel
//! count and order. Nothing here runs FFmpeg, so the test needs neither FFmpeg nor the fdk-aac
//! library.
//!
//! Acceptance: every channel of every container must correlate with the matching reference channel
//! at least `MIN_CORR` at the best lag in `-LAG_MAX..=LAG_MAX`, and the channel count and sample rate
//! must equal FFmpeg's. The lag search absorbs the decoder's start-up delay, and a swapped channel
//! fails because each fixture gives every channel a different signal.

use crate::common::deinterleave;
use crate::common::correlation;
use std::fs::File;
use std::io::BufReader;
use std::path::{Path, PathBuf};

use ec_aac::AacDecoder;
use ec_core::{CodecId, Demuxer, Packet};
use ec_mp4::Mp4Demuxer;

/// Per-channel correlation the reconstruction must reach against FFmpeg.
const MIN_CORR: f64 = 0.999;
/// Lag search bound, in samples, applied to each direction.
const LAG_MAX: i64 = 4096;
/// Window (in samples) the coarse lag search correlates over, and where it starts.
const WINDOW: usize = 8_192;
const WINDOW_START: usize = 4_096;

/// One fixture: its base name, the channel count and sample rate FFmpeg decodes it to.
struct Fixture {
    name: &'static str,
    channels: usize,
    rate: u32,
}

/// FFmpeg decodes the mono HE-AAC v1 stream as two identical channels ("Treating HE-AAC mono as
/// stereo"), so its reference has two channels. The 5.1 stream has six.
const FIXTURES: &[Fixture] = &[
    Fixture { name: "he_v1_mono", channels: 2, rate: 22_050 },
    Fixture { name: "he_v1_stereo", channels: 2, rate: 22_050 },
    Fixture { name: "he_v1_51", channels: 6, rate: 22_050 },
    Fixture { name: "he_v2_stereo", channels: 2, rate: 22_050 },
];

fn data_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/he")
}

/// FFmpeg's decode of the fixture, de-interleaved, scaled to [-1, 1].
fn reference(fixture: &Fixture) -> Vec<Vec<f32>> {
    let path = data_dir().join(format!("{}.s16", fixture.name));
    let bytes = std::fs::read(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    let samples: Vec<f32> = bytes
        .chunks(2)
        .filter(|b| b.len() == 2)
        .map(|b| f32::from(i16::from_le_bytes([b[0], b[1]])) / 32768.0)
        .collect();
    deinterleave(&samples, fixture.channels)
}

/// Decodes the `.aac` (ADTS) file in one call.
fn decode_adts(path: &Path) -> (u16, u32, Vec<f32>) {
    let bytes = std::fs::read(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    let audio = AacDecoder::new()
        .decode(&bytes, None)
        .unwrap_or_else(|e| panic!("{}: decode failed: {e:?}", path.display()));
    (audio.channels, audio.sample_rate, audio.samples)
}

/// Decodes the `.m4a` file access unit by access unit, using the `esds` AudioSpecificConfig.
fn decode_m4a(path: &Path) -> (u16, u32, Vec<f32>) {
    let mut demux = Mp4Demuxer::new(BufReader::new(File::open(path).expect("mp4 opens")))
        .unwrap_or_else(|e| panic!("{}: mp4 parse failed: {e:?}", path.display()));
    let (idx, asc) = {
        let aac = demux
            .streams()
            .iter()
            .find(|s| s.params.codec == CodecId::Aac)
            .expect("mp4 has an AAC track");
        let asc = aac.params.extradata.as_ref().expect("esds carries the ASC").to_vec();
        (aac.index, asc)
    };
    let mut decoder = AacDecoder::with_config_bytes(&asc).expect("ASC parses");
    let (mut channels, mut rate, mut samples) = (0u16, 0u32, Vec::new());
    while let Ok(Packet { stream, data, .. }) = demux.next_packet() {
        if stream != idx {
            continue;
        }
        let frame = decoder
            .decode(&data, None)
            .unwrap_or_else(|e| panic!("{}: access unit failed: {e:?}", path.display()));
        channels = frame.channels;
        rate = frame.sample_rate;
        samples.extend_from_slice(&frame.samples);
    }
    (channels, rate, samples)
}

/// The overlap of `ours` and `theirs` at `lag`: `ours[i]` pairs with `theirs[i + lag]`.
fn aligned<'a>(ours: &'a [f32], theirs: &'a [f32], lag: i64) -> (&'a [f32], &'a [f32]) {
    let (a0, b0) = if lag >= 0 { (0usize, lag as usize) } else { ((-lag) as usize, 0usize) };
    let n = ours.len().saturating_sub(a0).min(theirs.len().saturating_sub(b0));
    (&ours[a0..a0 + n], &theirs[b0..b0 + n])
}

/// The best lag in `-LAG_MAX..=LAG_MAX`, found on a window past the start-up transient, then
/// measured as the correlation over the full overlap at that lag. A winning lag on the bound is
/// refused: the true alignment may lie outside the search.
fn best_lag(ours: &[f32], theirs: &[f32]) -> (i64, f64) {
    let mut best = (0i64, 0.0f64);
    for lag in -LAG_MAX..=LAG_MAX {
        let (a, b) = aligned(ours, theirs, lag);
        if a.len() < WINDOW_START + WINDOW {
            continue;
        }
        let c = correlation(&a[WINDOW_START..WINDOW_START + WINDOW], &b[WINDOW_START..WINDOW_START + WINDOW]);
        if c.abs() > best.1.abs() {
            best = (lag, c);
        }
    }
    assert!(best.0.abs() < LAG_MAX, "winning lag {} sits at the search bound", best.0);
    let (a, b) = aligned(ours, theirs, best.0);
    (best.0, correlation(a, b))
}

#[test]
fn he_fixtures_match_ffmpeg_per_channel() {
    let mut failures = Vec::new();
    for fixture in FIXTURES {
        let theirs = reference(fixture);
        for (container, ext) in [("adts", "aac"), ("m4a", "m4a")] {
            let path = data_dir().join(format!("{}.{ext}", fixture.name));
            assert!(path.exists(), "fixture {} is absent", path.display());
            let (channels, rate, samples) =
                if ext == "aac" { decode_adts(&path) } else { decode_m4a(&path) };
            let label = format!("{} {container}", fixture.name);
            if usize::from(channels) != fixture.channels || rate != fixture.rate {
                failures.push(format!(
                    "{label}: decoded {channels} ch at {rate} Hz, FFmpeg {} ch at {} Hz",
                    fixture.channels, fixture.rate
                ));
                continue;
            }
            let ours = deinterleave(&samples, fixture.channels);
            for ch in 0..fixture.channels {
                let (lag, corr) = best_lag(&ours[ch], &theirs[ch]);
                println!(
                    "he {label} ch{ch}: ours {} frames, ffmpeg {} frames, lag {lag}, corr {corr:.6}",
                    ours[ch].len(),
                    theirs[ch].len()
                );
                if corr < MIN_CORR {
                    failures.push(format!("{label} ch{ch}: corr {corr:.6} < {MIN_CORR}"));
                }
            }
        }
    }
    assert!(failures.is_empty(), "HE-AAC does not match ffmpeg:\n{}", failures.join("\n"));
}
